import sys
from math import gcd

def find_sequence(n, k):
    if n == 1:
        return "-1" if k != 0 else "1"

    if k == 0:
        return " ".join(map(str, range(1, n + 1)))

    if k >= n - 1:
        return "-1"

    sequence = list(range(1, n + 1))
    current_gcd_sum = 0

    for i in range(n - 1):
        current_gcd_sum += gcd(sequence[i], sequence[i + 1])
        if current_gcd_sum > k:
